INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(245462, 'ruRU', '', 'Я занимаюсь тонкими делами разведки Орды. Для нас обоих будет лучше, если ты не станешь меня отвлекать.', 0),
(250597, 'ruRU', '', 'У нас пропадают грузы по всему Азероту. Если найдешь какой-нибудь, буду признателен, если вернешь его мне.', 0),
(292461, 'ruRU', '', 'Добро пожаловать в крепость Бандариона, $c.', 0),
(292462, 'ruRU', 'В прошлой жизни мой дом был неподалеку отсюда. Я до сих пор иногда брожу по полям родной фермы. Мне грустно видеть, как те, кто был мне знаком и дорог, бродят безмозглыми рабами. Это больно, но именно боль дает мне силу и цель.', '', 0),
(292463, 'ruRU', '', 'Почему меня зовут «Крушительница»?\r\n\r\nПоверь, тебе лучше не знать.', 0),
(292477, 'ruRU', 'Во тьме таится много всего, и Свет нужен сейчас как никогда. Если бы эти бедняги поняли: то, что наш мир изменился, не значит, что мы должны быть теми чудовищами, какими нас считают живые.', '', 0),
(299234, 'ruRU', '', 'Хвала Королеве-банши, гости у меня здесь бывают нечасто.', 0),
(300634, 'ruRU', 'Благословение Повелителя ветров течет сквозь меня!', 'Благословение Повелителя ветров течет сквозь меня!', 0),
(300635, 'ruRU', 'Ты $Gслышал:слышала; благую весть об Ал''акире, Повелителе ветров?', 'Ты $Gслышал:слышала; благую весть об Ал''акире, Повелителе ветров?', 0),
(300636, 'ruRU', 'Неверные будут очищены в наших славных бурях! Хвала Повелителю ветров!', 'Неверные будут очищены в наших славных бурях! Хвала Повелителю ветров!', 0),
(300637, 'ruRU', 'Бьется ли твое сердце в такт ветрам?', 'Бьется ли твое сердце в такт ветрам?', 0),
(302068, 'ruRU', '', 'Если бы Высший орден хоть немного думал о решении наших настоящих проблем и меньше помешался на древней магии, нам, как народу, было бы гораздо лучше. Именно магия высокорожденных погубила калдорай в свое время. И эти самовлюбленные глупцы хотят повторить те же ошибки!\r\n\r\nОдно то, что они пытались договориться с культом, уже плохо, но пролить кровь Ваятелей ветра – вот что воистину непростительно. Если бы не нависшая угроза культа, я бы собрал наши силы и покончил с Элаадрином и Высшим орденом раз и навсегда.', 0),
(302089, 'ruRU', '<Элаадрин смотрит на тебя с едва сдерживаемой ненавистью.> \r\n\r\nТы смеешь ступать в наше святилище после того, как $Gпролил:пролила; кровь Высшего ордена? Ты очень $Gхрабрый:храбрая; или очень $Gглупый:глупая;. Высший орден не прощает и не забывает.\r\n\r\nКогда-нибудь ты заплатишь за свои преступления кровью.', '', 0),
(302821, 'ruRU', 'Хочешь научиться кожевничеству?', 'Хочешь научиться кожевничеству?', 0),
(304015, 'ruRU', 'Приветствую… Ваятель ветра.\r\n\r\nТе, кто зовет себя Ваятелями ветра, находят мало общего с большинством членов Высшего ордена, как ты, должно быть, знаешь. За пределами относительного согласия Рощи Тендал ты убедишься, что эти разногласия очень глубоки и соперничество порой переходит в открытое насилие.\r\n\r\nБольше я ничего об этом не скажу, кроме одного: занимайся своими делами и не мешай целям Высшего ордена, когда покинешь рощу. Это, вероятно, единственное предупреждение, которое ты получишь.', '', 0),
(304291, 'ruRU', 'Лортуна проводит там какой-то обряд. Она может попытаться обрушить защитные чары!\r\n\r\nПомощь, за которой мы послали, еще не пришла, но придется обойтись тем, что есть. Когда будешь $Gготов:готова;, скажи, и мы отправимся ее остановить.', '', 0),
(304612, 'ruRU', 'Добро пожаловать в деревню Шен''дар, тут одна из лучших рыбалок по эту сторону горного хребта. Если хочешь научиться ловить рыбу, могу научить – за плату.', '', 0),
(304681, 'ruRU', '<Из-под металлических пластин брони создания доносится слабое жужжание. Ветер, приводящий эту машину в движение, едва теплится и лишь слегка шевелится. Не нужно много знать о воздушных созданиях, чтобы понять: этот образец явно нуждается в ремонте.>', '<Из-под металлических пластин брони создания доносится слабое жужжание. Ветер, приводящий эту машину в движение, едва теплится и лишь слегка шевелится. Не нужно много знать о воздушных созданиях, чтобы понять: этот образец явно нуждается в ремонте.>', 0),
(304790, 'ruRU', 'Что ты здесь делаешь? Быстро уходи отсюда. Ты все испортишь!', '', 0),
(304808, 'ruRU', '<Вращающийся перед тобой столб ветра, кажется, тихонько гудит от удовольствия. Говорить он не умеет, но ты ясно ощущаешь его чувства. Похоже, он… рад даровать тебе благословение ветров.>', '<Вращающийся перед тобой столб ветра, кажется, тихонько гудит от удовольствия. Говорить он не умеет, но ты ясно ощущаешь его чувства. Похоже, он… рад даровать тебе благословение ветров.>', 0),
(305322, 'ruRU', '', 'Приветствую и добро пожаловать, $n! Ты как раз вовремя: нашей компании «Снабжение и логистика Дуротара» всегда нужны новые подрядчики.\r\n\r\nЕсли ты умеешь добывать полезные материалы или создавать что-то с нуля, для тебя здесь найдется место.\r\n\r\nЕсли будут вопросы, дай знать.', 0),
(305506, 'ruRU', 'На что $Gуставился:уставилась;?', 'На что $Gуставился:уставилась;?', 0),
(305765, 'ruRU', 'Небоходы и паромы не ходят уже много лет. Кто знает, остались ли еще острова, откуда можно получать товары. Но я все равно здесь… на всякий случай.', 'Небоходы и паромы не ходят уже много лет. Кто знает, остались ли еще острова, откуда можно получать товары. Но я все равно здесь… на всякий случай.', 0),
(306575, 'ruRU', '', '$n, убедись, что все твои союзники готовы к бою, и поговори со мной, когда будешь $Gготов:готова; сразиться с Лортуной.', 0),
(306711, 'ruRU', '<Страж смерти Биллмут рассеянно ерзает и нервно озирается. Ему явно очень не по себе здесь.>', '<Страж смерти Биллмут рассеянно ерзает и нервно озирается. Ему явно очень не по себе здесь.>', 0),
(307829, 'ruRU', 'Приветствую, охотник. Я могу научить тебя умениям и приемам.', 'Приветствую, охотник. Я могу научить тебя умениям и приемам.', 0),
(308149, 'ruRU', 'Эй, чего тебе?', 'Эй, чего тебе?', 0),
(309795, 'ruRU', '', '<Валенниа морщится от боли, поворачиваясь к тебе.>\r\n\r\nНе смотри на меня так. Со мной все будет в порядке. Несмотря на все усилия встревоженных целителей Верховного старейшины, я скоро буду на ногах и снова готова драться.\r\n\r\nА теперь ступай… не задерживайся из-за старого солдата. Ветры принесут тебе удачу в пути, я знаю.', 0),
(309857, 'ruRU', '', 'Пожалуйста, не трогайте флаконы, если не собираетесь их купить.\r\n\r\nОтпечатки пальцев портят их ценность, понимаете ли.', 0),
(309858, 'ruRU', 'Лучшего снаряжения ты нигде не найдешь!', '', 0),
(309859, 'ruRU', 'О! Приветствую, друг. Не стесняйся, смотри мои товары.', '', 0),
(309860, 'ruRU', 'Эй, чего надо?', '', 0),
(309861, 'ruRU', '', 'Приветствую, друг! У меня большой запас кожи и шкур, и я знаю пару приемов, которыми, пожалуй, готов поделиться. Хочешь торговать?', 0),
(309862, 'ruRU', '<Джим''бек встречается с тобой взглядом, глубоко затягиваясь кальяном.>\r\n\r\nЗдорово, мон. Нужен ковер? Одеяло? Или просто ткань для следующей поделки? Я тебе все достану.', '', 0),
(309993, 'ruRU', '', 'Ишну-алах, путник, и добро пожаловать в Ночную Гавань.\r\n\r\nХочешь взглянуть на мой выбор красивых платьев?', 0),
(311965, 'ruRU', 'Еще одно новое лицо! Добро пожаловать в Азерот, приятель. Приходи ко мне, если нужна помощь, чтобы встать на ноги.\r\n\r\nС деньгами.', 'Еще одно новое лицо! Добро пожаловать в Азерот, приятель. Приходи ко мне, если нужна помощь, чтобы встать на ноги.\r\n\r\nС деньгами.', 0),
(312188, 'ruRU', 'Камень и земля говорят правдивее любого языка, если унять грохот в сердце и прислушаться.\r\n\r\nЕсли в тебе есть задатки шамана, я тебя научу.', 'Камень и земля говорят правдивее любого языка, если унять грохот в сердце и прислушаться.\r\n\r\nЕсли в тебе есть задатки шамана, я тебя научу.', 0),
(312224, 'ruRU', 'Ты уже $Gнашел:нашела; то, что нам нужно?', 'Ты уже $Gнашел:нашела; то, что нам нужно?', 0),
(313261, 'ruRU', 'Здравствуй, путник!', '', 0),
(315474, 'ruRU', 'Добро пожаловать в гильдейскую регистратуру Валанаара. Чем могу помочь?', 'Добро пожаловать в гильдейскую регистратуру Валанаара. Чем могу помочь?', 0),
(316076, 'ruRU', 'Мы, паладины, должны каждый день заслуживать свое место среди собратьев-Отрекшихся, чтобы нас не сочли фанатиками вроде Алого ордена. Свет – не просто орудие наших врагов, а проводник нашей праведной ярости! Именно благодаря преданности Темной Госпоже и любви к родному краю мы можем направлять Свет, чтобы нести правосудие нашим врагам.\r\n\r\nКоролева-банши зорко следит за нами. Пусть следит. Она увидит, что наша решимость не дрогнет. Мы – Отрекшиеся!', '', 0),
(316772, 'ruRU', '<Мясистые уши на его черепе слегка поворачиваются на атрофированных мышцах.>', '', 0),
(316813, 'ruRU', '<Оно скребет землю щербатым копытом.>', '', 0),
(316815, 'ruRU', '<Его глубокие пустые глазницы, кажется, сверлят тебя.>', '', 0),
(316817, 'ruRU', '<Оно щелкает зубами, грызя удила.>', '', 0),
(316863, 'ruRU', 'Добро пожаловать в мою лавку; приятно видеть еще одного портного здесь, в Валанааре. Не за уроком ли $Gпришел:пришела;?', 'Добро пожаловать в мою лавку; приятно видеть еще одного портного здесь, в Валанааре. Не за уроком ли $Gпришел:пришела;?', 0),
(317077, 'ruRU', 'Добро пожаловать в мою лавку; приятно видеть еще одного зачарователя здесь, в Валанааре. Не за уроком ли $Gпришел:пришела;?', 'Добро пожаловать в мою лавку; приятно видеть еще одного зачарователя здесь, в Валанааре. Не за уроком ли $Gпришел:пришела;?', 0),
(321462, 'ruRU', 'Ищешь гонца? Он только что улетел, как пташка.\r\n\r\nНе виню беднягу. Эти вендиго – та еще напасть.', 'Ищешь гонца? Он только что улетел, как пташка.\r\n\r\nНе виню беднягу. Эти вендиго – та еще напасть.', 0),
(321567, 'ruRU', '<Тело выглядит неполным и, кажется, ждет голову.>', '<Тело выглядит неполным и, кажется, ждет голову.>', 0),
(324914, 'ruRU', 'В последнее время приливы и отливы магии нарушены. Слышал, даже маги Даларана в замешательстве. Это возмущение арканы – или сами стихии неспокойны?', 'В последнее время приливы и отливы магии нарушены. Слышал, даже маги Даларана в замешательстве. Это возмущение арканы – или сами стихии неспокойны?', 0),
(325026, 'ruRU', 'Чего тебе?', '', 0),
(325066, 'ruRU', 'У меня лучшее мясо в Оргриммаре.', '', 0),
(325339, 'ruRU', 'Э? Ты слишком зеленый, чтобы иметь со мной дело.\r\n\r\nВозвращайся, когда немного освоишься с тем, как тут все устроено. Поверь мне.', '', 0),
(325752, 'ruRU', 'Для меня честь заниматься снабжением и провизией Служителей Земли. \r\n\r\nМои запасы пока невелики, но заглядывай почаще – у меня могут появиться новое снаряжение и припасы на продажу.', 'Для меня честь заниматься снабжением и провизией Служителей Земли. \r\n\r\nМои запасы пока невелики, но заглядывай почаще – у меня могут появиться новое снаряжение и припасы на продажу.', 0),
(325810, 'ruRU', 'Приветствую, гражданин. Чем могу помочь?', '', 0),
(325823, 'ruRU', 'Добро пожаловать в Крепость Штормграда, гражданин.', '', 0),
(325825, 'ruRU', 'Веди себя достойно в присутствии вождя, $c. Кор''кроны не потерпят здесь ни наглости, ни оскорблений.', '', 0),
(325830, 'ruRU', 'Я Вол''джин из племени Черного Копья. Ты друг или враг?', '', 0),
(325833, 'ruRU', '', '<Леди Сильвана Ветрокрылая молча смотрит на тебя.>', 0),
(326390, 'ruRU', 'Если ты $Gпришел:пришла; искать братство своих собратьев-паладинов, ты по адресу. \r\n\r\nДобро пожаловать домой.', 'Если ты $Gпришел:пришла; искать братство своих собратьев-паладинов, ты по адресу. \r\n\r\nДобро пожаловать домой.', 0),
(326579, 'ruRU', 'Мы заняты важными делами!', '', 0),
(326764, 'ruRU', 'Моя работа – снабжать паладинов крепости Бандариона достойным оружием и доспехами. Немного, но честный труд.\r\n\r\nЕсть у меня кое-что на продажу, если тебе нужно снаряжение.', 'Моя работа – снабжать паладинов крепости Бандариона достойным оружием и доспехами. Немного, но честный труд.\r\n\r\nЕсть у меня кое-что на продажу, если тебе нужно снаряжение.', 0),
(326872, 'ruRU', 'Моя клятва привязывает меня к этому месту. Что привело тебя в это забытое Светом место?', '', 0),
(326949, 'ruRU', 'Я Мулн Гнев Земли из Служителей Земли. Что привело тебя ко мне сегодня?', '', 0),
(326951, 'ruRU', 'Нам, шен''дорай, нужно больше ткани, чтобы пополнить запасы. Любые пожертвования пригодятся и непременно повысят твое уважение у Ваятелей ветра.', 'Нам, шен''дорай, нужно больше ткани, чтобы пополнить запасы. Любые пожертвования пригодятся и непременно повысят твое уважение у Ваятелей ветра.', 0),
(327153, 'ruRU', 'Этот неборез доставит тебя прямо на великолепные открытые равнины Мулгора.', '', 0),
(327642, 'ruRU', '', 'Чем могу помочь?', 0),
(327927, 'ruRU', '<Мертвый боевой конь склоняет голову набок и жует удила, разглядывая тебя.>', '', 0),
(327930, 'ruRU', '<Мертвый боевой конь вытягивает шею в твою сторону и смотрит на тебя двумя молочными немигающими глазами.>', '', 0),
(327932, 'ruRU', '<Боевой конь скребет землю, отчего нечестивое пламя вокруг его щербатого копыта колышется.>', '', 0),
(328261, 'ruRU', 'Добро пожаловать в парикмахерскую, друг! За стрижкой? Покраской? Чем-нибудь еще?\r\n\r\nМы можем подстричь бороду, сделать пирсинг, изменить бивни и рога и даже подправить черты нежити!\r\n\r\nПрисаживайся, и мы сразу приступим. Еще немного – и ты станешь новым, более привлекательным.', 'Добро пожаловать в парикмахерскую, друг! За стрижкой? Покраской? Чем-нибудь еще?\r\n\r\nМы можем подстричь бороду, сделать пирсинг, изменить бивни и рога и даже подправить черты нежити!\r\n\r\nПрисаживайся, и мы сразу приступим. Еще немного – и ты станешь новым, более привлекательным.', 0);
